router.post(
  "/api-conversion/v1/events",
  admitSignedRequest,
  express.raw({ type: () => true, inflate: false, limit: CONVERSION_MAX_BODY_BYTES }),
  async (req, res) => {
    const tracking = createTracking();
    const requestLogger = logger.child({ requestId: tracking.requestId });
    try {
      const receivedAt = utcNow();
      const signed = await authenticateSignedBody({ req, res, requestLogger, receivedAt });
      if (!signed) return;
      const { rawBody, access } = signed;
      const batch = parseConversionBatch(rawBody);
      if (!batch.ok) {
        requestLogger.info({ statusCode: batch.statusCode, error: batch.error }, "conversionApi.requestRejected");
        res.status(batch.statusCode).json({ error: batch.error });
        return;
      }
      // Charge the credential quota per event: a full batch of 100 costs 100.
      if (
        !(await consumeRateLimit(
          credentialLimiter,
          access.id,
          res,
          limits.ingestionCredential,
          limits.durationSeconds,
          batch.items.length,
        ))
      ) {
        // The IP-scoped limit above isn't logged the same way: it's already visible via
        // AppRequests' ResultCode/ClientIP with no app code involved. This one identifies which
        // credential hit its quota, which nothing else surfaces. An error, not a notice: the
        // quota is shared with referral code verification, so an integration that verifies on
        // every page view starves its own events, and this line is the only signal an operator
        // gets.
        requestLogger.error({ apiCredentialId: access.id, path: req.path }, "conversionApi.credentialRateLimited");
        res.status(429).json({ error: "too_many_requests" });
        return;
      }
      const { statusCode, receipt } = await ingestConversionEvents({
        db,
        logger: requestLogger,
        tracking,
        apiCredentialId: access.id,
        items: batch.items,
        receivedAt,
        testMode: batch.testMode,
      });
      // The one line that answers "what did this batch actually do" without a DB query: every
      // run through ingestion, success or failure, lands here exactly once.
      requestLogger.info(
        {
          apiCredentialId: access.id,
          count: receipt.count,
          accepted: receipt.accepted,
          duplicates: receipt.duplicates,
          failed: receipt.failed,
          testMode: batch.testMode,
        },
        "conversionApi.eventsIngested",
      );
      res.status(statusCode).json({
        count: receipt.count,
        accepted: receipt.accepted,
        duplicates: receipt.duplicates,
        failed: receipt.failed,
        errors: receipt.errors.map((error) => ({
          index: error.index,
          ...(error.eventId === undefined ? {} : { event_id: error.eventId }),
          status_code: error.statusCode,
          error: error.error,
        })),
        referral_codes: receipt.referralCodes.map(({ index, eventId, verification }) => ({
          index,
          event_id: eventId,
          ...toWireReferralCodeVerification(verification),
        })),
        clicks: receipt.clicks.map(({ index, eventId, attribution }) => ({
          index,
          event_id: eventId,
          attributed: attribution.attributed,
          ...(attribution.attributed ? {} : { reason: attribution.reason }),
        })),
        // One platform on the wire today; a second one gets its own key, never a merged array.
        meta: receipt.eligibility.flatMap(({ index, eventId, providers }) => {
          const answer = providers.meta;
          if (answer === undefined) return [];
          return [
            {
              index,
              event_id: eventId,
              eligible: answer.eligible,
              ...(answer.eligible ? {} : { reason: answer.reason }),
            },
          ];
        }),
      });
    } catch (err) {
      requestLogger.error(err, "conversionApi.requestFailed");
      res.status(500).json({ error: "internal_error" });
    }
  },
);

